<script setup>
import { ref, reactive, onMounted, onUnmounted, computed } from 'vue';
import { api, action, date } from '../api';
import { useRouter } from 'vue-router';
import { sourceHref, sourceQuote } from '../citations';
import CitedAnswer from '../components/CitedAnswer.vue';
import PageState from '../components/PageState.vue';
import KnowledgeScopePicker from '../components/KnowledgeScopePicker.vue';
import { ElMessageBox } from 'element-plus';
const router=useRouter();
const activeTab=ref('search');
const form=reactive({question:'',bookIds:[],publicOnly:false,searchMode:'hybrid',mode:'qa',rerank:true});
const results=ref(null),messages=ref([]),sessions=ref([]),current=ref(null),busy=ref(false),searching=ref(false),error=ref(''),loading=ref(true);
let alive=true,selection=0;
const modes={qa:'知识问答',summary:'多文档总结',compare:'知识对比'};
const scopeDescription=computed(()=>form.bookIds.length?`已选择 ${form.bookIds.length} 本 Book`:form.publicOnly?'公开书库中的就绪内容':'我拥有和被分享的就绪内容');
async function list(){const data=await api('/api/conversations');if(alive)sessions.value=data;}
function changeScope(){form.bookIds=[];}
async function fresh(){current.value=null;messages.value=[];results.value=null;error.value='';selection++;}
async function choose(session){if(busy.value)return;const run=++selection;await action(async()=>{const data=await api('/api/conversations/'+session.id);if(!alive||run!==selection)return;current.value=data;messages.value=data.messages;form.bookIds=data.scope.bookIds;form.publicOnly=data.scope.publicOnly;form.mode=data.mode;form.searchMode=data.scope.searchMode||'hybrid';form.rerank=data.scope.rerank!==false;error.value='';});}
async function remove(session){try{await ElMessageBox.confirm('删除对话记录不会影响 Book。','删除对话',{confirmButtonText:'删除记录',cancelButtonText:'保留'});}catch{return;}await action(async()=>{await api('/api/conversations/'+session.id,{method:'DELETE'});if(current.value?.id===session.id)await fresh();await list();});}
async function search(){if(!form.question.trim())return;searching.value=true;error.value='';const run=selection;try{const data=await api('/api/knowledge/search',{method:'POST',body:form});if(alive&&run===selection)results.value=data;}catch(e){if(alive)error.value=e.message;}finally{if(alive)searching.value=false;}}
async function send(){const question=form.question.trim();if(!question||busy.value)return;busy.value=true;error.value='';const run=selection;
  try{if(!current.value){const created=await api('/api/conversations',{method:'POST',body:{title:question.slice(0,80),bookIds:form.bookIds,publicOnly:form.publicOnly,mode:form.mode,searchMode:form.searchMode,rerank:form.rerank}});if(!alive||run!==selection)return;current.value={id:created.id,scope:{bookIds:[...form.bookIds],publicOnly:form.publicOnly},mode:form.mode};}
    const id=current.value.id;messages.value.push({role:'user',content:question,status:'RUNNING'});form.question='';
    const data=await api(`/api/conversations/${id}/messages`,{method:'POST',body:{question}});if(!alive||run!==selection)return;results.value=null;const detail=await api('/api/conversations/'+id);if(!alive||run!==selection)return;messages.value=detail.messages;await list();
  }catch(e){if(alive&&run===selection){error.value=e.message;const pending=messages.value.at(-1);if(pending?.role==='user')pending.status='FAILED';form.question=question;}}
  finally{if(alive)busy.value=false;}
}
onMounted(async()=>{try{await list();}catch(e){if(alive)error.value=e.message;}finally{if(alive)loading.value=false;}});onUnmounted(()=>{alive=false;selection++;});
</script>
<template><section><div class="page-heading"><div><h1>全库知识工作台</h1><p>检索并核对原文，支持跨 Book 总结与对比。</p></div><el-button v-if="activeTab === 'search'" :disabled="busy" @click="fresh">新建对话</el-button></div><el-tabs v-model="activeTab" class="knowledge-tabs" aria-label="知识工作台功能"><el-tab-pane label="检索与问答" name="search"><div class="knowledge-search-layout"><aside class="knowledge-panel knowledge-sidebar"><h2>检索范围</h2><el-radio-group v-model="form.publicOnly" :disabled="!!current||busy" aria-label="知识范围" @change="changeScope"><el-radio-button :value="false">我的知识</el-radio-button><el-radio-button :value="true">公开书库</el-radio-button></el-radio-group><label for="knowledge-books">指定 Book 或文件夹（留空为全部）</label><KnowledgeScopePicker id="knowledge-books" v-model="form.bookIds" :public-only="form.publicOnly" :disabled="!!current||busy" label="选择检索 Book 或文件夹" empty-text="全部就绪资料，可按 Book 或分类选择" /><label for="knowledge-mode">对话方式</label><el-select id="knowledge-mode" v-model="form.mode" :disabled="!!current||busy"><el-option v-for="(name,key) in modes" :key="key" :label="name" :value="key"/></el-select><p class="muted">{{scopeDescription}}。对话建立后固定范围；需要更换时新建对话。</p><h2 class="conversation-heading">历史对话</h2><ul class="conversation-list"><li v-for="s in sessions" :key="s.id" :class="{selected:current?.id===s.id}"><button :disabled="busy" @click="choose(s)"><strong>{{s.title}}</strong><small>{{modes[s.mode]}} · {{date(s.updatedAt)}}</small></button><button :disabled="busy" class="delete-conversation" :aria-label="`删除对话 ${s.title}`" @click="remove(s)">×</button></li></ul><p v-if="!sessions.length" class="muted">登录后的对话会保存在你的空间，可在其他设备继续。</p></aside><main class="knowledge-panel knowledge-main"><PageState :loading="loading" :error="loading?error:''" @retry="list"><div class="search-method"><span>{{current?modes[current.mode]:modes[form.mode]}}</span><el-select v-model="form.searchMode" :disabled="!!current||busy" aria-label="搜索方式"><el-option value="hybrid" label="混合检索"/><el-option value="semantic" label="语义搜索"/><el-option value="fulltext" label="全文与精确匹配"/><el-option value="keyword" label="关键词搜索"/></el-select><el-checkbox v-model="form.rerank" :disabled="!!current||busy">模型重排</el-checkbox></div><div v-if="!messages.length" class="knowledge-empty"><h2>让不同资料彼此印证</h2><p>可以问“这些资料如何解释同一个概念”，也可以选择两本 Book，对比它们的方案。</p><p class="muted">回答只采用本轮检索的原文；找不到依据时会明确说明。</p></div><div class="knowledge-transcript" aria-live="polite"><article v-for="(m,index) in messages" :key="m.id||index" :class="['knowledge-message',m.role]"><small>{{m.role==='user'?'你':'知识助手'}}{{m.status==='FAILED'?' · 本次未完成':''}}</small><CitedAnswer v-if="m.role==='assistant'" :content="m.content" :sources="m.sources||[]" @cite="(source,quote)=>router.push(sourceHref(source,quote))"/><p v-else>{{m.content}}</p></article><p v-if="busy" class="muted">正在检索并核对出处…</p></div><p v-if="error" class="error" role="alert">{{error}}</p><form class="knowledge-composer" @submit.prevent="send"><label for="global-question">{{form.mode==='summary'?'想总结哪些主题？':form.mode==='compare'?'想比较哪些内容？':'向知识库提问'}}</label><el-input id="global-question" v-model="form.question" type="textarea" :rows="3" maxlength="500" show-word-limit placeholder="例如：比较这些资料中的异常处理方案" :disabled="busy"/><div class="composer-actions"><span class="muted">搜索查看原文；提问生成带出处的回答。</span><el-button :loading="searching" :disabled="busy||!form.question.trim()" @click="search">只搜索</el-button><el-button type="primary" native-type="submit" :loading="busy" :disabled="!form.question.trim()">{{modes[form.mode]}}</el-button></div></form><section v-if="results" class="knowledge-results"><div class="search-result-heading"><h2>本轮原文片段</h2><small>{{results.rerankMode==='gte-rerank-v2'?'模型重排':results.rerankMode==='rrf-fallback'?'重排服务暂不可用，采用融合排序':'融合排序'}} · {{results.results?.length||0}} 段</small></div><p v-if="!results.results?.length" class="muted">当前范围没有匹配片段。可换用关键词、调整范围，或等待索引完成。</p><article v-for="r in results.results" :key="r.chunkId"><RouterLink :to="sourceHref(r,sourceQuote(r,form.question))">{{r.bookTitle}}<span v-if="r.fileId"> · {{r.sourceName}}</span><span v-if="r.page"> · 第 {{r.page}} 页</span></RouterLink><p>{{r.excerpt?.slice(0,400)}}{{r.excerpt?.length>400?'…':''}}</p></article></section></PageState></main></div></el-tab-pane></el-tabs></section></template>